def eliminate_subqueries(expression: E) -> E:
    """
    Rewrite derived tables as CTES, deduplicating if possible.

    Example:
        >>> import sqlglot
        >>> expression = sqlglot.parse_one("SELECT a FROM (SELECT * FROM x) AS y")
        >>> eliminate_subqueries(expression).sql()
        'WITH y AS (SELECT * FROM x) SELECT a FROM y AS y'

    This also deduplicates common subqueries:
        >>> expression = sqlglot.parse_one("SELECT a FROM (SELECT * FROM x) AS y CROSS JOIN (SELECT * FROM x) AS z")
        >>> eliminate_subqueries(expression).sql()
        'WITH y AS (SELECT * FROM x) SELECT a FROM y AS y CROSS JOIN y AS z'

    Args:
        expression (sqlglot.Expr): expression
    Returns:
        sqlglot.Expr: expression
    """
    if isinstance(expression, exp.Subquery):
        # It's possible to have subqueries at the root, e.g. (SELECT * FROM x) LIMIT 1
        eliminate_subqueries(expression.this)
        return expression

    root = build_scope(expression)

    if not root:
        return expression

    # Map of alias->Scope|Table
    # These are all aliases that are already used in the expression.
    # We don't want to create new CTEs that conflict with these names.
    taken: TakenNameMapping = {}

    # All CTE aliases in the root scope are taken
    for scope in root.cte_scopes:
        parent = scope.expression.parent
        if parent:
            taken[parent.alias] = scope

    # All table names are taken
    for scope in root.traverse():
        taken.update(
            {
                source.name: source
                for _, source in scope.sources.items()
                if isinstance(source, exp.Table)
            }
        )

    # Map of Expr->alias
    # Existing CTES in the root expression. We'll use this for deduplication.
    existing_ctes: ExistingCTEsMapping = {}

    with_: exp.With | None = root.expression.args.get("with_")
    recursive: bool | None = False
    if with_:
        recursive = with_.args.get("recursive")
        with_exprs: list[exp.CTE] = with_.expressions
        for cte in with_exprs:
            existing_ctes[cte.this] = cte.alias
    new_ctes: list[exp.Expr] = []

    # We're adding more CTEs, but we want to maintain the DAG order.
    # Derived tables within an existing CTE need to come before the existing CTE.
    for cte_scope in root.cte_scopes:
        # Append all the new CTEs from this existing CTE
        for scope in cte_scope.traverse():
            if scope is cte_scope:
                # Don't try to eliminate this CTE itself
                continue
            new_cte = _eliminate(scope, existing_ctes, taken)
            if new_cte:
                new_ctes.append(new_cte)

        # Append the existing CTE itself
        cte_parent = cte_scope.expression.parent
        if cte_parent:
            new_ctes.append(cte_parent)

    # Now append the rest
    for scope in itertools.chain(
        root.set_operation_scopes, root.subquery_scopes, root.table_scopes
    ):
        for child_scope in scope.traverse():
            new_cte = _eliminate(child_scope, existing_ctes, taken)
            if new_cte:
                new_ctes.append(new_cte)

    if new_ctes:
        query = expression.expression if isinstance(expression, exp.DDL) else expression
        if not isinstance(query, exp.Query):
            # This can be reached for DMLs, which shouldn't hold the WITH clause; attach it to
            # the root query, which is also where any pre-existing CTEs in `new_ctes` came from
            query = root.expression.unnest()

        query.set("with_", exp.With(expressions=new_ctes, recursive=recursive))

    return expression

def prune_projections(
    reachability: ProjectionReachability,
    root: int,
    journal: Journal | None = None,
    remove_ctes: bool = True,
) -> None:
    """Prune the analyzed tree to the scopes and projections reachable from root output index root.

    Use root=0 for reachability computed with whole_query=True. Required companion outputs, such
    as the other projections of SELECT DISTINCT, are retained as well.

    This edits SELECT projection lists, renumbers bare GROUP BY ordinals, and removes
    unused CTEs unless remove_ctes is false. Other clauses remain in their containing
    expressions; their dependencies keep the outputs those clauses reference.

    Grouping ordinals and set-operation names were saved during analysis, before pruning.
    Mutations are recorded in journal, if given, so the original tree can be restored before
    pruning for another root output.
    """
    # Visit parents before their children when removing unused CTEs.
    bit = 1 << root
    for scope in reversed(reachability.scopes):
        if not reachability.live[scope] & bit:
            if remove_ctes and scope.is_cte:
                cte_node = scope.expression.parent
                if isinstance(cte_node, exp.CTE):
                    with_node = cte_node.parent
                    if journal is not None and with_node is not None:
                        record(journal, with_node, "expressions")

                    cte_node.pop()

                    if with_node is not None and not with_node.expressions:
                        if journal is not None and with_node.parent is not None:
                            record(journal, with_node.parent, "with_")

                        with_node.pop()
            continue

        expression = scope.expression
        if not isinstance(expression, exp.Select):
            continue

        subset = [
            selection
            for selection, roots in zip(expression.selects, reachability.selections[scope])
            if roots & bit
        ]
        if len(subset) == len(expression.selects):
            continue

        ordinal_refs = reachability.group_by_ordinals[scope]
        if not subset:
            placeholder = default_selection(reachability.is_agg[scope])
            ancestor = scope

            while ancestor.is_set_operation and ancestor.parent:
                ancestor = ancestor.parent
                retained_name = next(
                    (
                        name
                        for name, roots in zip(
                            reachability.set_names[ancestor], reachability.selections[ancestor]
                        )
                        if roots & bit
                    ),
                    None,
                )
                if retained_name is not None:
                    # An empty BY NAME arm must contribute NULL under an existing output name.
                    # A new `_` column would change the width of an enclosing positional union.
                    placeholder.set(
                        "this",
                        exp.Max(this=exp.Null()) if reachability.is_agg[scope] else exp.Null(),
                    )
                    placeholder.set("alias", exp.to_identifier(retained_name, quoted=True))
                    break

            subset = [placeholder]

        if journal is not None:
            record(journal, expression, "expressions")

        expression.set("expressions", subset)

        if ordinal_refs:
            new_pos = {id(selection): i + 1 for i, selection in enumerate(subset)}
            for node, old_selection in ordinal_refs:
                pos = new_pos.get(id(old_selection))
                if pos is not None and int(node.this) != pos:
                    if journal is not None:
                        record(journal, node, "this")

                    node.set("this", str(pos))

def get_source_columns(self, name: str, only_visible: bool = False) -> Sequence[str]:
        """Resolve the source columns for a given source `name`."""
        cache_key = (name, only_visible)
        if cache_key not in self._get_source_columns_cache:
            if name not in self.scope.sources:
                raise OptimizeError(f"Unknown table: {name}")

            source = self.scope.sources[name]

            # A pivoted CTE reference is stored as an exp.Table in the scope sources (see
            # _traverse_tables in scope.py), but the underlying CTE Scope still holds the
            # column information we need to resolve pre-pivot columns.
            if (
                isinstance(source, exp.Table)
                and not source.db
                and source.args.get("pivots")
                and source.name in self.scope.cte_sources
            ):
                source = self.scope.cte_sources[source.name]

            if isinstance(source, exp.Table):
                columns = self.schema.column_names(source, only_visible)
            elif isinstance(source, Scope) and isinstance(
                source_expr := source.expression, (exp.Values, exp.Unnest, exp.Lateral)
            ):
                columns = source_expr.named_selects

                # in bigquery, unnest structs are automatically scoped as tables, so you can directly select
                # a struct field in a query. This handles the case where the unnest is statically defined.
                if self.dialect.UNNEST_COLUMN_ONLY and isinstance(source_expr, exp.Unnest):
                    if not source_expr.type or source_expr.type.is_type(exp.DType.UNKNOWN):
                        unnest_expr = seq_get(source_expr.expressions, 0)
                        if isinstance(unnest_expr, exp.Column) and self.scope.parent:
                            col_type = self._get_unnest_column_type(unnest_expr, self.scope.parent)
                            if col_type and col_type.is_type(exp.DType.ARRAY):
                                element_types = col_type.expressions
                                if element_types:
                                    source_expr.type = element_types[0].copy()
                            elif col_type:
                                source_expr.type = col_type.copy()

                    columns.extend(self._struct_field_names(source_expr.type))
                elif isinstance(source_expr, exp.Lateral) and isinstance(
                    source_expr.this, exp.Explode
                ):
                    explode_col = source_expr.this.this

                    # If the column is unqualified at this point, it couldn't be resolved when
                    # this scope's children were qualified; disambiguating it here would require
                    # enumerating this very source's columns, i.e recurse without bound
                    if isinstance(explode_col, exp.Column) and explode_col.table and source.parent:
                        col_type = self._get_unnest_column_type(explode_col, source.parent)
                        columns.extend(self._struct_field_names(col_type))
                elif isinstance(source_expr, exp.Lateral) and isinstance(
                    source_expr.this, exp.Query
                ):
                    columns = source_expr.this.named_selects
            elif isinstance(source, Scope) and isinstance(source.expression, exp.SetOperation):
                columns = self.get_source_columns_from_set_op(source.expression)
            else:
                selectable = source.expression.assert_is(exp.Selectable)
                select = seq_get(selectable.selects, 0)

                if isinstance(select, exp.QueryTransform):
                    # https://spark.apache.org/docs/3.5.1/sql-ref-syntax-qry-select-transform.html
                    schema = select.args.get("schema")
                    columns = [c.name for c in schema.expressions] if schema else ["key", "value"]
                else:
                    columns = selectable.named_selects

            node, _ = self.scope.selected_sources.get(name) or (None, None)
            if isinstance(node, Scope):
                column_aliases = node.expression.alias_column_names
            elif isinstance(node, exp.Expr):
                column_aliases = node.alias_column_names
            else:
                column_aliases = []

            if column_aliases:
                # If the source's columns are aliased, their aliases shadow the corresponding column names.
                # This can be expensive if there are lots of columns, so only do this if column_aliases exist.
                columns = [
                    alias or name
                    for (name, alias) in itertools.zip_longest(columns, column_aliases)
                ]

            self._get_source_columns_cache[cache_key] = columns

        return self._get_source_columns_cache[cache_key]

